import { useEffect, useRef, type KeyboardEvent } from "react";

import type { IdServiceDeLaMarque } from "@/shared/config/services-de-la-marque";

import { Glyphe } from "./Glyphe";
import {
  DisqueDuRail,
  Entete,
  Fermer,
  Maillon,
  Onglets,
  Panneau,
  PastilleDuService,
  Pied,
  Plongee,
  Rail,
  TitreDuService,
  Voisin,
} from "./plongee.styles";
import ServiceEnDetail from "./ServiceEnDetail";
import { CONTENU_DES_SERVICES } from "./systeme.contenu";
import { NOEUDS_DU_RESEAU } from "./systeme.reseau";

/**
 * La plongée — la navigation interne du système du cabinet.
 *
 * CE QUI CLOCHAIT (vu le 2026-09-25) : une branche ouverte était un mur de
 * texte — trois colonnes d'une cinquantaine de mots, la carte floutée derrière,
 * un rail de neuf points muets, un « Fermer » posé au coin, hors de la scène.
 *
 * CE QU'ELLE FAIT : le réseau recule sans disparaître, et l'orbite se déroule
 * en rail — le centre en tête (retour à la vue d'ensemble), puis les douze
 * services par leur glyphe. Le panneau montre une vignette codée et les fiches
 * du service ; la fiche active pilote la vignette, avance seule avec sa barre,
 * et s'arrête au survol comme au focus.
 *
 * LE RAIL EST UNE LISTE D'ONGLETS (motif ARIA « tabs ») : ← → passent d'un
 * service à l'autre, Échap revient au réseau et rend le focus au service ouvert.
 *
 * Chargée au premier clic (`React.lazy`) : ni ses vignettes ni son panneau ne
 * pèsent sur le premier écran.
 */

function IconeCentre() {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
      <circle cx="12" cy="12" r="8.5" fill="none" stroke="currentColor" strokeWidth={1.4} />
      <path d="M3.5 12h17 M12 3.5c3 2.6 3 14.4 0 17 M12 3.5c-3 2.6-3 14.4 0 17" fill="none" stroke="currentColor" strokeWidth={1.2} />
      <circle cx="12" cy="12" r="1.8" fill="currentColor" />
    </svg>
  );
}

function IconeFermer() {
  return (
    <svg viewBox="0 0 16 16" aria-hidden="true" focusable="false">
      <path d="M3.5 3.5l9 9 M12.5 3.5l-9 9" fill="none" stroke="currentColor" strokeWidth={1.8} strokeLinecap="round" />
    </svg>
  );
}

export default function PlongeeDuSysteme({
  serviceId,
  mouvementReduit,
  onChanger,
  onFermer,
}: {
  serviceId: IdServiceDeLaMarque;
  mouvementReduit: boolean;
  onChanger: (id: IdServiceDeLaMarque) => void;
  onFermer: () => void;
}) {
  const index = NOEUDS_DU_RESEAU.findIndex((n) => n.id === serviceId);
  const noeud = NOEUDS_DU_RESEAU[index];
  const contenu = CONTENU_DES_SERVICES[serviceId];
  const titre = useRef<HTMLHeadingElement>(null);
  const onglets = useRef<Array<HTMLButtonElement | null>>([]);

  /* Un autre service : le titre prend le focus — le lecteur d'écran annonce où
     l'on est arrivé. */
  useEffect(() => {
    titre.current?.focus();
  }, [serviceId]);

  const voisin = (pas: number) =>
    NOEUDS_DU_RESEAU[(index + pas + NOEUDS_DU_RESEAU.length) % NOEUDS_DU_RESEAU.length];

  const surTouche = (evenement: KeyboardEvent<HTMLElement>) => {
    if (evenement.key === "Escape") {
      evenement.stopPropagation();
      onFermer();
      return;
    }
    const dansLeRail = (evenement.target as HTMLElement).closest("[role='tablist']");
    if (!dansLeRail || (evenement.key !== "ArrowRight" && evenement.key !== "ArrowLeft")) return;
    evenement.preventDefault();
    const suivant = voisin(evenement.key === "ArrowRight" ? 1 : -1);
    onChanger(suivant.id);
    requestAnimationFrame(() => onglets.current[NOEUDS_DU_RESEAU.indexOf(suivant)]?.focus());
  };

  const precedent = voisin(-1);
  const suivant = voisin(1);

  return (
    <Plongee aria-label={`${noeud.libelle} — en détail`} onKeyDown={surTouche}>
      <Rail>
        <DisqueDuRail
          type="button"
          data-centre="true"
          aria-label="Revenir au réseau des services"
          onClick={onFermer}
        >
          <IconeCentre />
        </DisqueDuRail>
        <Onglets role="tablist" aria-label="Les services">
        {NOEUDS_DU_RESEAU.map((n, i) => (
          <span key={n.id} style={{ display: "contents" }}>
            <Maillon aria-hidden="true" />
            <DisqueDuRail
              ref={(el) => {
                onglets.current[i] = el;
              }}
              type="button"
              role="tab"
              id={`plongee-onglet-${n.id}`}
              aria-selected={n.id === serviceId}
              aria-controls="plongee-panneau"
              aria-label={n.libelle}
              tabIndex={n.id === serviceId ? 0 : -1}
              onClick={() => onChanger(n.id)}
            >
              <Glyphe trace={n.glyphe} />
            </DisqueDuRail>
          </span>
        ))}
        </Onglets>
      </Rail>

      <Panneau id="plongee-panneau" role="tabpanel" aria-labelledby={`plongee-onglet-${serviceId}`}>
        <Entete>
          <PastilleDuService aria-hidden="true">
            <Glyphe trace={noeud.glyphe} />
          </PastilleDuService>
          <TitreDuService ref={titre} tabIndex={-1}>
            {contenu.titre}
          </TitreDuService>
        </Entete>
        <Fermer type="button" onClick={onFermer} aria-label="Revenir au réseau des services">
          <IconeFermer />
        </Fermer>

        <ServiceEnDetail serviceId={serviceId} mouvementReduit={mouvementReduit} />

        <Pied>
          <Voisin type="button" onClick={() => onChanger(precedent.id)}>
            <span aria-hidden="true">←</span>
            {precedent.libelle}
          </Voisin>
          <Voisin type="button" onClick={() => onChanger(suivant.id)}>
            {suivant.libelle}
            <span aria-hidden="true">→</span>
          </Voisin>
        </Pied>
      </Panneau>
    </Plongee>
  );
}
